import { z } from 'zod/v3';

export const PREVIEW_ROUTE_LIMIT = 32;
const PREVIEW_ROUTE_MAX_LENGTH = 2_048;

export const previewRouteSchema = z
  .string()
  .max(PREVIEW_ROUTE_MAX_LENGTH)
  .refine((route) => {
    let pathname: string;
    try {
      pathname = decodeURIComponent(route.split(/[?#]/)[0]);
    } catch {
      return false;
    }
    return (
      route.startsWith('/') &&
      !route.startsWith('//') &&
      !route.includes('\\') &&
      !/^\/%(?:2f|5c)/i.test(route) &&
      !pathname.includes('\\') &&
      !pathname
        .split('/')
        .some((segment) => segment === '.' || segment === '..') &&
      ![...route].some(
        (character) => character <= ' ' || character === '\u007f',
      )
    );
  }, 'Expected an app-relative preview route');

export const previewRoutesSchema = z
  .array(previewRouteSchema)
  .min(1)
  .max(PREVIEW_ROUTE_LIMIT)
  .transform((routes) => [...new Set(routes)]);

export const mergePreviewRoutes = (
  ...groups: (readonly string[] | undefined)[]
): string[] =>
  [...new Set(groups.flatMap((routes) => routes ?? []))].slice(
    0,
    PREVIEW_ROUTE_LIMIT,
  );
